CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER, c1 TEXT DEFAULT 'd', c2 ANY) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(-229, 'a%b', 'it''s');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT, c1 TEXT);
INSERT OR IGNORE INTO t1(c0, c1) VALUES('Ελλάδα', 'delta');
INSERT OR IGNORE INTO t1(c0, c1) VALUES(NULL, NULL);
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -2, 5), instr('0x1F', 'naïve'), replace('0x1F', 'a', ''), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE '%a_', '0x1F' GLOB '*', char(79, 305), '0x1F' || 'naïve', '0x1F' < 'naïve', '0x1F' = 'naïve' COLLATE NOCASE;
SELECT length('1e3'), upper('1e3'), lower('1e3'), substr('1e3', -2, 1), instr('1e3', 'beta'), replace('1e3', 'e', 'XY'), trim('1e3'), ltrim('1e3', 'ab'), hex('1e3'), quote('1e3'), unicode('1e3'), '1e3' LIKE 'A%', '1e3' GLOB '*[a-m]*', char(83, 319), '1e3' || 'beta', '1e3' < 'beta', '1e3' = 'beta' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', 3, 0), instr('iota', 'kappa'), replace('iota', 'é', ''), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE '%a_', 'iota' GLOB '*', char(82, 949), 'iota' || 'kappa', 'iota' < 'kappa', 'iota' = 'kappa' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', -3, 0), instr('a%b', 'naïve'), replace('a%b', 'e', 'XY'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '%', 'a%b' GLOB '?', char(66, 260), 'a%b' || 'naïve', 'a%b' < 'naïve', 'a%b' = 'naïve' COLLATE NOCASE;
SELECT length('beta'), upper('beta'), lower('beta'), substr('beta', 4, 3), instr('beta', 'nu'), replace('beta', 'e', 'XY'), trim('beta'), ltrim('beta', 'ab'), hex('beta'), quote('beta'), unicode('beta'), 'beta' LIKE '%', 'beta' GLOB '?', char(76, 562), 'beta' || 'nu', 'beta' < 'nu', 'beta' = 'nu' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 0, 4), instr('Lambda', 'tau'), replace('Lambda', 'a', '_'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE 'a%', 'Lambda' GLOB 'a*', char(87, 267), 'Lambda' || 'tau', 'Lambda' < 'tau', 'Lambda' = 'tau' COLLATE NOCASE;
SELECT length('psi'), upper('psi'), lower('psi'), substr('psi', 1, 4), instr('psi', '42'), replace('psi', 'é', '_'), trim('psi'), ltrim('psi', 'ab'), hex('psi'), quote('psi'), unicode('psi'), 'psi' LIKE '%', 'psi' GLOB '*[a-m]*', char(65, 839), 'psi' || '42', 'psi' < '42', 'psi' = '42' COLLATE NOCASE;
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c2 DESC, id DESC;
SELECT id FROM t0 WHERE id NOT IN (SELECT id FROM t1) ORDER BY id;
SELECT id FROM t0 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 3) ORDER BY id;
SELECT c1 FROM t0 EXCEPT SELECT c1 FROM t1 ORDER BY 1 LIMIT 6 OFFSET 1;
SELECT count(*), count(id), sum(id), total(id), avg(id), min(id), max(id), count(DISTINCT id) FROM t0 WHERE 'rho' BETWEEN -('theta') AND CAST(NULL AS REAL);
SELECT id, count(*), group_concat(id) FROM (SELECT * FROM t0 ORDER BY id) GROUP BY id ORDER BY id;
